    tension: { choice: tension.choice as (typeof SCENE_TENSION_OPTIONS)[number], probability: tension.probability, uncertain: tension.probability < 0.6 },
    usage: result.usage,
  } };
}

export interface SceneProposal { dimension: SceneDimension; text: string; origin: "writer" }
export type SceneMedium = "image" | "sound" | "motion";

/** This prepares text locally. It does not call or imply a media provider. */
export function createSceneMediaBrief(inventory: SceneInventory, medium: SceneMedium, proposals: readonly SceneProposal[] = []): string | null {
  if (inventory.status !== "ready") return null;
  const unidentified = SCENE_DIMENSIONS.filter(({ id }) => !inventory.dimensions[id].length).map(({ label }) => label.toLowerCase());
  return [
    `Exploratory ${medium} brief`,
    "Source excerpt (verbatim, the only manuscript evidence):",
    inventory.passage.text,
    "Details not identified by the local cue scan (absence of a cue is not proof of absence):",
    unidentified.length ? unidentified.join(", ") : "A cue was found for every inventory dimension.",
    "Writer-proposed additions (not facts from the manuscript):",
    ...proposals.filter((p) => p.origin === "writer" && p.text.trim()).map((p) => `${SCENE_DIMENSIONS.find(({ id }) => id === p.dimension)?.label ?? "Idea"}: ${p.text.trim()}`),
    proposals.some((p) => p.origin === "writer" && p.text.trim()) ? "" : "None.",
    "Keep explicit source details intact. Label any additional staging, sound, light, or movement as an interpretation. This brief does not authorize a provider request or set a budget.",
  ].filter(Boolean).join("\n\n");
}

export function sceneSpeechId(passage: ScenePassage): string { return `scene:${scenePassageKey(passage)}`; }

/** Shares Twyne's selected narration provider, cache, transport, and stop control. */
export async function startSceneNarration(passage: ScenePassage, options: Pick<import("./speech").SpeakRequest, "client" | "signedIn"> = {}): Promise<void> {
  if (createSceneInventory(passage).status !== "ready") throw new Error("Select a valid scene before reading it aloud.");
  const { speak } = await import("./speech");
  await speak({ text: passage.text, id: sceneSpeechId(passage), sourceOffset: passage.sourceOffset, label: "Selected scene", progressive: true, ...options });
}

