    busy: false, error: "", assessment: null as SceneAssessment | null,
    notesKey: "", proposals: [] as SceneProposal[], draft: "", dimension: "light" as SceneDimension,
    notesReady: false, saving: false, noteMessage: "", medium: "image" as SceneMedium,
    brief: "", briefPassage: null as ScenePassage | null, copied: false,
  });

  // Load only when the selected passage changes; this is not a keystroke listener.
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track, cleanup }) => {
    const snapshot = track(() => inventory.value);
    let disposed = false;
    cleanup(() => { disposed = true; });
    ui.notesReady = false;
    ui.notesKey = snapshot.key;
    ui.proposals = [];
    ui.draft = "";
    ui.noteMessage = "";
    if (snapshot.status !== "ready") return;
    try {
      const proposals = await loadSceneProposals(snapshot.passage);
      if (!disposed && sceneSnapshotMatches(snapshot, props.passage)) {
        ui.proposals = proposals;
        ui.notesReady = true;
      }
    } catch {
      if (!disposed) ui.noteMessage = "Local idea storage is unavailable. You can still inspect this passage.";
    }
  });

  const current = inventory.value;
  const assessment = ui.assessment && sceneSnapshotMatches(ui.assessment, props.passage) ? ui.assessment : null;
  const proposals = ui.notesKey === current.key ? ui.proposals : [];
  const activeSpeech = speech.state.id === sceneSpeechId(props.passage) && ["loading", "playing", "paused"].includes(speech.state.status);
  const briefCurrent = ui.briefPassage && sceneSnapshotMatches({ passage: ui.briefPassage }, props.passage);

  return (
    <InstrumentMotion state={assessment ? "arrive" : "rest"} quiet={props.quiet} class="scene-bench">
      <header class="scene-bench__head">
        <InstrumentArt kind="scene" size="compact" />
        <div><h2>Scene bench</h2><p>See what the passage gives you, then try an idea.</p></div>
      </header>
      {current.status !== "ready" ? <p class="scene-bench__notice">{current.reason}</p> : <>
        <details class="scene-bench__source">
          <summary>Selected passage · {current.spans.length} {current.spans.length === 1 ? "sentence" : "sentences"}</summary>
          <blockquote>{props.passage.text}</blockquote>
        </details>
        <p class="scene-bench__method">Local English cue scan. A quoted cue is evidence to inspect; an unlisted detail may still be present.</p>
        <dl class="scene-bench__inventory">
          {SCENE_DIMENSIONS.map(({ id, label }) => {
            const model = assessment?.dimensions[id];
            const selected = model?.state === "selected" ? current.spans.find((span) => span.id === model.spanId) : null;
            const local = current.dimensions[id];
            const spans = selected ? [selected] : local.slice(0, 2).flatMap((cue) => current.spans.filter((span) => span.id === cue.spanId));
            return <div key={id} class="scene-bench__dimension" data-scene-dimension={id}>
              <dt>{label}</dt><dd>
                {spans.map((span) => <div class="scene-bench__evidence" key={span.id}>
                  <blockquote>{span.text}</blockquote>
                  <div class="scene-bench__evidence-foot"><span>{selected ? `${assessment!.model} selection` : "Local word cue"}</span>
                    {props.onLocate$ && <button type="button" onClick$={async () => {
                      if (sceneSpanMatches(span, props.passage)) await props.onLocate$?.(span, props.passage);
                    }}>Find in passage</button>}
                  </div>
                </div>)}
                {!spans.length && <p class="scene-bench__unidentified">No cue identified locally.</p>}
                {local.length > 2 && !selected && <p class="scene-bench__method">Showing 2 of {local.length} local cues.</p>}
                {model?.state === "uncertain" && <p class="scene-bench__method">The model reading was uncertain; local cues remain for inspection.</p>}
                {model?.state === "not-identified" && <p class="scene-bench__method">The model did not identify explicit evidence for this dimension.</p>}
              </dd>
            </div>;
          })}
        </dl>

        <details class="scene-bench__provider">
          <summary>Ask for a model reading</summary>
          <p>Selects evidence and reads the scene's pressure. It does not rewrite or add scene details.</p>
          <p class="scene-bench__method">{canRequest(props.judgement) && props.onJudge$
            ? `Sends this selected passage to ${props.judgement!.destination}. ${props.judgement!.costLabel}`
            : props.judgement?.unavailableReason ?? "No judgement provider is connected here. The local inventory remains available."}</p>
          <button type="button" disabled={ui.busy || !canRequest(props.judgement) || !props.onJudge$} onClick$={async () => {
            if (!props.onJudge$ || !canRequest(props.judgement) || ui.busy) return;
            const snapshot = createSceneInventory(props.passage);
            const request = createSceneJudgementRequest(snapshot);
            if (!request) return;
            ui.busy = true; ui.error = "";
            try {
              const result = resolveSceneJudgement(snapshot, await props.onJudge$(request), props.passage);
              if (result.ok) ui.assessment = result.assessment;
              else ui.error = result.reason === "stale" ? "The passage changed while the model read it. Ask again for this version." : "The model did not return a usable reading. The local inventory is still available.";
            } catch { ui.error = "The model reading is unavailable. The local inventory is still available."; }
            finally { ui.busy = false; }
          }}>{ui.busy ? "Reading the passage…" : "Read the scene with a model"}</button>
        </details>
        {ui.error && <p class="scene-bench__notice" role="status">{ui.error}</p>}
        {ui.assessment && !assessment && <p class="scene-bench__notice">The previous model reading belongs to an earlier selection.</p>}
        {assessment && <InstrumentMotionPart part="result" class="scene-bench__reading">
          <InstrumentRule />
          <h3>{assessment.tension.uncertain ? "The scene pressure is uncertain" : SCENE_TENSION_LABELS[assessment.tension.choice]}</h3>
          <p class="scene-bench__method">{assessment.model} reading · {Math.round(assessment.tension.probability * 100)}% probability for this interpretation. This is not a writing grade.</p>
        </InstrumentMotionPart>}

        <section class="scene-bench__section" aria-label="Read the scene aloud">
          <h3>Hear the passage</h3>
          <p class="scene-bench__method">{canRequest(props.narration) && props.onRead$
            ? `Reads this selected text using ${props.narration!.destination}. ${props.narration!.costLabel}`
            : props.narration?.unavailableReason ?? "Connect a narration provider to hear this passage. No audio request has been made."}</p>
          <div class="scene-bench__actions">
            <button type="button" disabled={activeSpeech ? speech.state.status === "loading" : !canRequest(props.narration) || !props.onRead$} onClick$={async () => {
              if (activeSpeech) { await speech.toggle$(); return; }
              if (!props.onRead$ || !canRequest(props.narration)) return;
              ui.error = "";
              try { await props.onRead$(props.passage); }
              catch { ui.error = "The scene could not be read aloud. Check the narration provider and try again."; }
            }}>{activeSpeech ? speech.state.status === "loading" ? "Preparing voice…" : speech.state.status === "playing" ? "Pause reading" : "Resume reading" : "Read scene aloud"}</button>
            {activeSpeech && <button type="button" onClick$={speech.stop$}>Stop reading</button>}
          </div>
        </section>

        <section class="scene-bench__section" aria-label="Proposed scene details">
          <h3>Try a detail</h3>
          <p class="scene-bench__method">Your ideas stay separate from the manuscript. Saved on this device for this exact selection.</p>
          {proposals.length > 0 && <ul class="scene-bench__ideas">{proposals.map((proposal, i) => <li key={`${i}:${proposal.text}`}>
            <strong>{SCENE_DIMENSIONS.find(({ id }) => id === proposal.dimension)?.label}</strong><p>{proposal.text}</p><span class="scene-bench__method">Your proposed addition</span>
          </li>)}</ul>}
          <label class="scene-bench__field">Explore<select value={ui.dimension} onChange$={(_, element) => { ui.dimension = element.value as SceneDimension; }}>{SCENE_DIMENSIONS.map(({ id, label }) => <option value={id} key={id}>{label}</option>)}</select></label>
          <label class="scene-bench__field">An idea to try<textarea value={ui.draft} maxLength={600} rows={3} placeholder="For example: a lamp flickering in the window." onInput$={(_, element) => { ui.draft = element.value; }} /></label>
          <button type="button" disabled={!ui.draft.trim() || ui.saving || !ui.notesReady || proposals.length >= 12} onClick$={async () => {
            if (!ui.draft.trim() || ui.saving || !ui.notesReady || ui.proposals.length >= 12) return;
            const passage = { ...props.passage };
            const next: SceneProposal[] = [...ui.proposals, { dimension: ui.dimension, text: ui.draft.trim(), origin: "writer" }];
            ui.saving = true;
            try {
              await saveSceneProposals(passage, next);
              if (sceneSnapshotMatches({ passage }, props.passage)) { ui.proposals = next; ui.draft = ""; ui.noteMessage = "Idea saved on this device. The manuscript is unchanged."; ui.brief = ""; }
            } catch { ui.noteMessage = "The idea could not be saved locally. It is still in the field."; }
            finally { ui.saving = false; }
          }}>{ui.saving ? "Saving idea…" : "Save this idea"}</button>
          {proposals.length >= 12 && <p class="scene-bench__method">Twelve ideas are saved for this selection. Use them in a brief before collecting more.</p>}
          {ui.noteMessage && <p class="scene-bench__method" role="status">{ui.noteMessage}</p>}
        </section>

        <section class="scene-bench__section" aria-label="Prepare a media brief">
          <h3>Explore an image, sound, or movement</h3>
          <p class="scene-bench__method">Media generation is not connected to this instrument. Preparing a brief stays on this device, sends nothing, and incurs no generation charge.</p>
          <div class="scene-bench__actions">{(["image", "sound", "motion"] as const).map((medium) => <button type="button" key={medium} onClick$={() => {
            ui.medium = medium; ui.brief = createSceneMediaBrief(inventory.value, medium, ui.proposals) ?? ""; ui.briefPassage = { ...props.passage }; ui.copied = false;
          }}>Prepare {medium} brief</button>)}</div>
          {ui.brief && briefCurrent && <div class="scene-bench__brief">
            <label class="scene-bench__field">{ui.medium[0].toUpperCase() + ui.medium.slice(1)} brief<textarea value={ui.brief} readOnly rows={8} /></label>
            <button type="button" onClick$={async () => {
              try { await navigator.clipboard.writeText(ui.brief); ui.copied = true; }
              catch { ui.noteMessage = "Copy is unavailable. Select the brief text and copy it with your keyboard."; }
            }}>{ui.copied ? "Brief copied" : "Copy brief"}</button>
          </div>}
        </section>
      </>}
    </InstrumentMotion>
  );
});

.scene-bench {
  max-inline-size: 40rem;
  min-inline-size: 0;
  padding: 1.25rem;
  color: var(--color-ink);
  background: var(--color-paper);
  font: 0.875rem/1.55 var(--font-sans);
}
.scene-bench__head { display: flex; align-items: center; gap: 1rem; margin-block-end: 1rem; }
.scene-bench h2 { margin: 0 0 0.25rem; font: 600 1.125rem/1.3 var(--font-sans); }
.scene-bench h3 { margin: 0 0 0.5rem; font: 600 1rem/1.35 var(--font-sans); }
.scene-bench p { margin: 0; }
.scene-bench__head p { color: var(--color-ink-light); }
.scene-bench__method, .scene-bench__unidentified, .scene-bench__evidence-foot { color: var(--color-ink-light); font-size: 0.75rem; }
.scene-bench__method { margin-block: 0.5rem !important; }
.scene-bench__source { padding-block: 0.75rem; border-block: 1px solid var(--color-paper-3); }
.scene-bench summary { cursor: pointer; min-block-size: 2rem; padding-block: 0.25rem; font-weight: 500; }
.scene-bench blockquote { margin: 0.5rem 0 0; padding: 0; white-space: pre-wrap; overflow-wrap: anywhere; font: 0.9375rem/1.65 var(--font-serif); }
.scene-bench__inventory { margin: 0; }
.scene-bench__dimension { display: grid; grid-template-columns: 5.5rem minmax(0, 1fr); gap: 1rem; padding-block: 1rem; border-block-end: 1px solid var(--color-paper-3); }
.scene-bench dt { padding-block-start: 0.375rem; font-weight: 600; }
.scene-bench dd { margin: 0; min-inline-size: 0; }
.scene-bench__unidentified { padding-block-start: 0.375rem; }
.scene-bench__evidence + .scene-bench__evidence { margin-block-start: 1rem; }
.scene-bench__evidence-foot { display: flex; align-items: center; flex-wrap: wrap; gap: 0.375rem 0.75rem; margin-block-start: 0.5rem; }
.scene-bench__evidence-foot button { padding: 0.25rem 0 !important; border: 0 !important; text-decoration: underline; text-underline-offset: 0.2em; min-block-size: 2rem !important; }
.scene-bench__provider { padding-block: 1rem; }
.scene-bench__section { border-block-start: 1px solid var(--color-paper-3); padding-block: 1.25rem; }
.scene-bench__section:last-child { padding-block-end: 0; }
.scene-bench__actions { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-block-start: 0.75rem; }
.scene-bench button { padding: 0.5rem 0.75rem; border: 1px solid var(--color-ink-light); min-block-size: 2.75rem; background: transparent; color: var(--color-ink); font: 500 0.8125rem/1.3 var(--font-sans); cursor: pointer; }
.scene-bench button:hover:not(:disabled) { background: var(--color-paper-2); }
.scene-bench button:active:not(:disabled) { background: var(--color-paper-3); }
.scene-bench button:disabled { cursor: default; opacity: 0.6; }
.scene-bench :is(button, textarea, select, summary):focus-visible { outline: 2px solid var(--color-cobalt); outline-offset: 3px; }
.scene-bench__field { display: flex; flex-direction: column; gap: 0.375rem; margin-block: 0.75rem; color: var(--color-ink-light); font-size: 0.8125rem; }
.scene-bench :is(textarea, select) { inline-size: 100%; min-inline-size: 0; border: 1px solid var(--color-ink-light); border-radius: 0; padding: 0.5rem; background: var(--color-paper-soft); color: var(--color-ink); font: 0.875rem/1.5 var(--font-sans); }
.scene-bench textarea { resize: vertical; }
.scene-bench textarea::placeholder { color: var(--color-ink-light); opacity: 1; }
.scene-bench__ideas { list-style: none; margin: 1rem 0; padding: 0; }
.scene-bench__ideas li { padding-block: 0.75rem; border-block-start: 1px solid var(--color-paper-3); overflow-wrap: anywhere; }
.scene-bench__ideas strong { font-size: 0.75rem; }
.scene-bench__notice { padding: 0.75rem; background: var(--color-paper-2); color: var(--color-ink-light); }
.scene-bench__reading { padding-block: 0.25rem 1rem; }
.scene-bench__reading .instrument-art__rule { margin-block-end: 0.75rem; }
.scene-bench__brief { margin-block-start: 1rem; }
@media (max-width: 30rem) {
  .scene-bench { padding: 1rem; }
  .scene-bench__dimension { grid-template-columns: minmax(0, 1fr); gap: 0.25rem; }
  .scene-bench__head { gap: 0.75rem; }
}

