/** Public manual illustrations use staged, non-personal application data. */
export interface ManualGuideStep {
  title: string;
  instruction: string;
  image: string;
  alt: string;
  width: number;
  height: number;
}

export interface ManualGuide {
  title: string;
  summary: string;
  /** A short, reader-facing boundary, e.g. a staged editorial reading. */
  note?: string;
  steps: ManualGuideStep[];
}

export type ManualGuides = Record<string, ManualGuide>;
import type { ManualGuides } from "./manual-guide-types";

const assets = "/assets/manual/living-desk/";

export const LIVING_DESK_GUIDES = {
  "the-piece": {
    title: "Follow a pattern across the piece",
    summary:
      "Find the passages behind a pattern, try a change, and keep the choices that belong to your voice.",
    note: "An actual local walkthrough with a fictional manuscript. These checks and fixes work without a model; the overall score shown is an estimate.",
    steps: [
      {
        title: "Open The piece",
        instruction:
          "In the Compositor, choose Review, then The piece. The small score beside the manuscript opens it too. The desk brings together shifts in stance, spelling variants, style exceptions and gaps between a name’s appearances.",
        image: `${assets}01-piece-overview.webp`,
        alt: "The piece beside a sample flood memoir, showing an approximate score, a Consistency measure, Stance, Names, Style and Presence lenses, and findings tied to the manuscript.",
        width: 1440,
        height: 900,
      },
      {
        title: "Inspect and preview",
        instruction:
          "Open Editorial ‘we’ in an ‘I’ essay. The flagged passages come first; other plural and singular uses are folded below. Hover or keyboard-focus a proposed fix to preview it on the page. The preview leaves your draft unchanged.",
        image: `${assets}02-preview.webp`,
        alt: "The expanded stance finding shows passages and Make it I controls, with a temporary replacement preview in the sample manuscript.",
        width: 1440,
        height: 900,
      },
      {
        title: "Make a change you can undo",
        instruction:
          "Choose Make it I for one passage, or Make all for the listed fixes. The manuscript and local consistency measure update together. Use your usual Undo shortcut to reverse the change; a batch is one undo step. Uses referring to a real group are left alone.",
        image: `${assets}03-revised.webp`,
        alt: "After applying one proposed fix, the manuscript reads I argue and the stance finding counts two remaining editorial uses of we.",
        width: 1440,
        height: 900,
      },
      {
        title: "Keep an intentional exception",
        instruction:
          "Similar spellings can be different names. If Hollis and Hollins are distinct in your piece, choose Hollis is a different name. That choice stays with this folio on this device. Check these again restores the finding; new, unaccepted occurrences can still be flagged.",
        image: `${assets}04-deliberate.webp`,
        alt: "A naming finding marked as deliberate, with its explanation and Check these again control visible.",
        width: 1440,
        height: 900,
      },
      {
        title: "Trace someone through the sections",
        instruction:
          "Open a presence finding to see which headed sections mention a recurring name. Select a passage to go to it; the Presence lens marks the names in the manuscript. A gap is an invitation to inspect the structure, not a request to insert a character. Press Escape to clear the focus, then again to close the desk.",
        image: `${assets}05-presence.webp`,
        alt: "A section-by-section presence table shows Mara Okafor appearing before and after the waterline section, with related names highlighted in the manuscript.",
        width: 1440,
        height: 900,
      },
    ],
  },
} satisfies ManualGuides;
import type { ManualFilm } from "./manual-video";

export const MANUAL_FILMS: Record<string, ManualFilm> = {
  "the-piece": {
    id: "living-desk",
    title: "The piece · Follow a pattern, try a revision",
    duration: "20 sec",
    description: "Inspect a shift in voice, try and undo a fix, then follow a name across the sections.",
    transcript: "A fictional flood memoir is open beside The piece. The writer opens a finding about editorial ‘we’, previews ‘I’ on the page, then applies one change. The draft and consistency measure update. Undo restores the original. The writer keeps two similar names distinct and opens the presence table to follow a recurring name across sections. The demonstration uses real local checks without a model request.",
    width: 1440,
    height: 900,
    credit: "Silent walkthrough · Fictional manuscript · Local rules",
  },
  "getting-started": {
    id: "newsreel",
    title: "Newsreel · A writing room in miniature",
    duration: "34 sec",
    description:
      "A short newsreel introduction to the brief and the five editorial voices.",
    transcript:
      "A black-and-white newsreel announces a writing room for the modern writer. Title cards introduce the sceptic, patron, scholar, copy chief and reader, then return to the brief that gives a draft its direction. This is an editorial introduction; the walkthrough below shows the current application controls.",
    width: 1280,
    height: 720,
    credit: "English · Editorial film · AI narration",
  },
  dossier: {
    id: "the-strike",
    title: "The Strike · Finding the right words",
    duration: "15 sec",
    description:
      "An animated headline is typed, questioned and revised: a short introduction to giving a piece a direction.",
    transcript:
      "A portrait-format film types and strikes through Twyne’s opening headlines, using the rhythm of correction to arrive at the editorial room. Music and typewriter sounds accompany the on-screen words. The dossier walkthrough below shows how to set the purpose of your own piece.",
    width: 720,
    height: 1280,
    credit: "English titles · Editorial film · Music and typewriter sounds",
  },
  house: {
    id: "house-context",
    title: "The House · Follow the context",
    duration: "18 sec",
    description:
      "Follow a sample folio through its collection, House defaults and register.",
    transcript:
      "The recording opens a sample folio in the House, inspects its inherited fields, visits the collection and House, then follows the register and assembled model context. It uses a sample manuscript and local application state. No account or model request is demonstrated.",
    width: 1152,
    height: 720,
    credit: "Silent walkthrough · Sample manuscript",
  },
  room: {
    id: "roll-call",
    title: "Roll Call · Meet the five editors",
    duration: "46 sec",
    description:
      "Hear each resident voice give its characteristic reading of a draft.",
    transcript:
      "The five editors arrive in turn. Mlle. Sceptique tests the assumption that a reader agrees. Sœur Encourageante protects the line with a pulse. Professeur Athenæum asks for evidence. M. Le Stylo cuts unnecessary words. Le Lecteur reports where he loses the thread. The cast returns together around one desk.",
    width: 1280,
    height: 720,
    credit: "English · Editorial film · AI voices",
  },
  marginalia: {
    id: "edited",
    title: "Edited · Five readings of one passage",
    duration: "46 sec",
    description:
      "Watch the room challenge an inflated opening, preserve a useful word and find a clearer promise.",
    transcript:
      "A sample promotional paragraph is typed onto the page. The copy chief cuts empty adjectives, the sceptic challenges an absolute claim, the scholar asks for the evidence behind a productivity figure, and the patron keeps the word ‘writing’. A revised sentence earns the reader’s attention. The film illustrates the editors’ distinct lenses; the walkthrough shows how a real margin conversation works.",
    width: 1280,
    height: 720,
    credit: "English · Staged editorial example · AI voices",
  },
  "manuscript-tools": {
    id: "source-workspace",
    title: "Source & proof · From draft to page",
    duration: "7 sec",
    description:
      "A sample manuscript moves through the source tools and its printed proof.",
    transcript:
      "The recording uses a sample draft to show the manuscript tools, source workspace and paginated proof. The source controls preserve the writer’s selection and the proof displays the editorial sheet. It demonstrates local tools, without publishing the manuscript or contacting a model.",
    width: 1152,
    height: 720,
    credit: "Silent walkthrough · Sample manuscript",
  },
  folios: {
    id: "sting",
    title: "The room’s signature",
    duration: "6 sec",
    description:
      "The griffin and wordmark close the editorial films. A small signature before your work leaves the desk.",
    transcript:
      "The Twyne griffin and wordmark appear in a six-second closing card with a brief musical signature. This is a brand film; the steps below show the export and publishing controls.",
    width: 1280,
    height: 720,
    credit: "Closing film · Musical signature",
  },
};

