          )}
          <button
            type="button"
            disabled={!supported.value || !!busy.value}
            onClick$={() => download(pack)}
          >
            {statuses[pack]?.phase === "ready"
              ? "Load / check pack"
              : "Download & load"}
          </button>
          {!!statuses[pack]?.downloadedBytes && (
            <button
              type="button"
              disabled={!!busy.value}
              onClick$={async () => {
                await removeLocalWriting(pack);
                statuses[pack] = await localWritingStatus(pack);
              }}
            >
              Remove pack
            </button>
          )}
          {busy.value === pack && (
            <button
              type="button"
              onClick$={() => {
                abort.value?.abort();
                stopLocalWriting();
              }}
            >
              Stop download
            </button>
          )}
        </div>
      ))}
      <section class="pack">
        <h3>Compare nearby passages</h3>
        <label>
          Passages, separated by a blank line
          <textarea
            value={passage.value}
            maxLength={16000}
            onInput$={(_, el) => (passage.value = el.value)}
          />
        </label>
