              const pieces = passage.value
                .split(/\n\s*\n/)
                .map((t) => t.trim())
                .filter(Boolean);
              if (pieces.length < 2)
                throw new Error(
                  "Add at least two passages separated by a blank line.",
                );
              const vectors = await embedWritingPassages(pieces);
              comparison.pairs = pieces
                .slice(1)
                .map((b, i) => ({
