const store = useStore<SelectionActionsStore>({
  personas: DEFAULT_PERSONAS,
  personaOpen: false,
});

// eslint-disable-next-line qwik/no-use-visible-task
useVisibleTask$(async () => {
  const custom = await loadPersonasFromIdb();
  if (custom?.length) store.personas = custom;
});

const selection = props.selection;
if (!selection) return null;

return (
  <div
    class={["selection-actions", `selection-actions--${selection.placement}`]}
    style={{ left: `${selection.x}px`, top: `${selection.y}px` }}
    role="toolbar"
    aria-label={`Actions for “${selection.text.slice(0, 70)}”`}
    // This must be declarative: a Qwik onMouseDown$ handler runs after the
    // browser has already collapsed the ProseMirror range. Keeping the
    // range lets every action act on the passage the writer just selected.
    preventdefault:mousedown
  >
    <div class="selection-actions__quote" title={selection.text}>
      “{selection.text.slice(0, 82)}
      {selection.text.length > 82 ? "…" : ""}”
    </div>
    <div class="selection-actions__row">
      {props.onSentenceBench$ && (
        <button
          type="button"
          onClick$={props.onSentenceBench$}
          disabled={props.disabled}
        >
          {/\s/.test(selection.text.trim())
            ? "Sentence bench"
            : "Word alternatives"}
        </button>
      )}
      {props.onHear$ && (
        <button
          type="button"
          onClick$={props.onHear$}
          disabled={props.disabled}
        >
          Hear
        </button>
      )}
      {props.onThreads$ && /\s/.test(selection.text.trim()) && (
        <button
          type="button"
          onClick$={props.onThreads$}
          disabled={props.disabled}
        >
          Threads
        </button>
      )}
      {props.onSceneBench$ && /\s/.test(selection.text.trim()) && (
        <button
          type="button"
          onClick$={props.onSceneBench$}
          disabled={props.disabled}
        >
          Scene bench
        </button>
      )}
      {props.onTaskDesk$ && (
        <button
          type="button"
          onClick$={props.onTaskDesk$}
          disabled={props.disabled}
        >
          Task desk
        </button>
      )}
    </div>
    <div class="selection-actions__row">
      <button
        type="button"
        onClick$={props.onGetSources$}
        disabled={props.disabled}
      >
        Get sources
      </button>
      <button
        type="button"
        onClick$={props.onAddMargin$}
        disabled={props.disabled}
      >

