              text={note.streamingReply}
              color={note.color}
            />
          </div>
        )}
        {note.replying && !note.streamingReply.trim() && (
          <div
            class="persona-note-typing flex items-center gap-2 pt-1 italic text-[0.75rem] text-[var(--color-ink-muted)]"
