              </button>
              <button
                onClick$={() => onReply$(note.id, note.draft, note.author)}
                disabled={!note.draft.trim()}
                class="btn-press text-[11px] disabled:opacity-30 disabled:cursor-not-allowed"
              >
                Reply
              </button>
            </div>
          </div>
        </div>
      </div>
