    background: #2e3801;
    color: #d2d2d2;
    font-family: monospace;
    padding: 3px 5px;
    pointer-events: all;
    margin: 0;
    border: 0;
    cursor: pointer;
    font-size: 11px;
    width: calc(100% - 24px);
    text-overflow: ellipsis;
    overflow: hidden;
    display: block;
    direction: rtl;
    text-align: right;
  }
  #loc:hover {
    background: #3a4a01;
  }

  pre {
    background: #f1fb8e;
    padding: 5px;
    margin: 5px 0;
    border-radius: 3px;
    user-select: none;
  }

  pre span {
    user-select: all;
  }

  a {
    text-decoration: underline;
  }

  #close {
    border: 0;
    width: 25px;
    height: 25px;
    position: absolute;
    right: 0;
    top: 0;
    background: #ffe14f;
    color: black;
    font-weight: 900;
    padding: 0;
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    cursor: pointer;
  }
  #close:hover {
    background: #ffeb6f;
  }

  #action-btn {
    border: 2px solid #18ae00;
    padding: 2px 4px;
    background: #50ff50;
    border-radius: 5px;
    color: #0c5500;
    font-weight: 800;
    font-size: 10px;
    cursor: pointer;
  }

  p {
    margin: 5px 0;
  }

  h2 {
    font-weight: 900;
    margin: 10px 0;
  }
