+import { readFile, writeFile } from "node:fs/promises";
+import { createHash } from "node:crypto";
+import { fileURLToPath } from "node:url";
+import sharp from "sharp";
+
+const directory = fileURLToPath(new URL("./", import.meta.url));
+const cases = [
+  ["light", "Paper", "Two familiar voices, with their names and roles above sample critiques."],
+  ["night", "Nightpress", "The same component in the app’s night palette. The faces stay readable."],
+  ["narrow", "320px", "A real 320px browser viewport. The names wrap, and the portraits keep their shape."],
+  ["cast", "The five editors", "All five existing ink portraits, plus two explicit custom-persona fallbacks."],
+];
+const images = [];
+for (const [id, label, caption] of cases) {
+  const source = await readFile(`${directory}${id}.png`);
+  const buffer = await sharp(source).webp({ quality: 88, effort: 6 }).toBuffer();
+  const metadata = await sharp(buffer).metadata();
+  await writeFile(`${directory}${id}.webp`, buffer);
+  images.push({ id, label, caption, width: metadata.width, height: metadata.height, bytes: buffer.length, sha256: createHash("sha256").update(source).digest("hex"), data: `data:image/webp;base64,${buffer.toString("base64")}` });
+}
+const verification = JSON.parse(await readFile(`${directory}verification.json`, "utf8"));
+const proof = { capturedAt: verification.capturedAt, source: verification.provenance, checks: verification.checks.length, images: images.map(({ data, ...image }) => image) };
+const html = `<!doctype html>
+<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Twyne · Recognizable editorial voices</title><style>
+*{box-sizing:border-box}html,body{margin:0;background:transparent;color:var(--foreground,#28261f)}body{font:14px/1.6 var(--font-sans,system-ui,sans-serif)}main{width:100%;max-width:960px;margin:auto}h1,p,figure,h2{margin:0}h1{font:500 29px/1.2 Georgia,serif;letter-spacing:-.02em;max-width:28ch;margin:4px 0 12px}.intro{max-width:62ch;color:var(--muted-foreground,#646159);margin-bottom:22px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.tabs button{font:inherit;font-size:13px;min-height:40px;padding:8px 13px;border:1px solid var(--border,#d3cebf);border-radius:7px;background:transparent;color:inherit;cursor:pointer}.tabs button[aria-pressed=true]{background:var(--secondary,#eee9dc);border-color:var(--foreground,#28261f);font-weight:600}.viewport{padding:16px;background:var(--card,#eee9dc);border-radius:var(--radius,12px);max-height:550px;overflow:auto;display:flex;justify-content:center;align-items:flex-start}.viewport img{display:block;width:100%;height:auto;align-self:flex-start}.viewport.narrow img{width:288px;max-width:100%}figcaption{font-size:12px;line-height:1.6;color:var(--muted-foreground,#646159);margin-top:10px}figcaption strong{color:var(--foreground,#28261f);font-weight:600}.notes{display:grid;grid-template-columns:1fr 1fr;gap:24px;border-top:1px solid var(--border,#d3cebf);padding-top:20px;margin-top:22px}.notes h2{font:600 15px/1.5 var(--font-sans,system-ui,sans-serif);margin-bottom:6px}.notes p{font-size:13px;color:var(--muted-foreground,#646159)}.proof{font-size:12px;color:var(--muted-foreground,#646159);border-top:1px solid var(--border,#d3cebf);padding:14px 0;margin-top:20px}.proof a{color:inherit;text-underline-offset:3px}.proof p+p{margin-top:6px}button:focus-visible,a:focus-visible{outline:2px solid var(--ring,#486276);outline-offset:4px}[hidden]{display:none!important}@media(max-width:520px){h1{font-size:26px}.notes{grid-template-columns:1fr;gap:16px}.viewport{max-height:530px}.tabs{gap:6px}.tabs button{padding:8px 10px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
+</style></head><body><main>
+<h1>A familiar face above each critique.</h1>
+<p class="intro">The room’s existing ink portraits now sit beside the editor’s name and role. The voices are recognizable at a glance, while the writing stays central.</p>
+<div class="tabs" role="group" aria-label="Choose a component capture">${images.map((item, index) => `<button type="button" data-view="${item.id}" aria-controls="capture-${item.id}" aria-pressed="${index === 0}">${item.label}</button>`).join("")}</div>
+${images.map((item, index) => `<figure id="capture-${item.id}" ${index ? "hidden" : ""}><div class="viewport ${item.id === "narrow" ? "narrow" : ""}"><img src="${item.data}" width="${item.width}" height="${item.height}" alt="Actual component capture: ${item.caption}"></div><figcaption><strong>${item.label}.</strong> ${item.caption} Sample critiques; no model request. Scroll the image to inspect the full capture.</figcaption></figure>`).join("")}
+<div class="notes"><section><h2>Names keep their meaning.</h2><p>A known persona ID selects its own portrait. A custom persona keeps its initials, even when its name matches a resident editor. Older notes without an ID use an exact name match only.</p></section><section><h2>Quiet while you read.</h2><p>Static head-and-shoulder crops, fixed geometry, and visible names. The image is decorative for assistive technology; discussion and reading controls remain with the critique.</p></section></div>
+<footer class="proof"><p>Actual Qwik Storybook captures · four browser views passed · five identity tests passed. Light and night text contrast checked. This sheet shows component fixtures, not a live provider run or a hosted release.</p><p><a href="verification.json">Local verification</a> · <a href="cast.png">Full cast capture</a> · <a href="https://twyne.love/docs/#writing-instruments" target="_blank" rel="noopener">Writing instruments guide ↗</a></p></footer>
+</main><script type="application/json" id="provenance">${JSON.stringify(proof)}</script><script>
+const buttons=[...document.querySelectorAll('[data-view]')];function show(id){buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===id)));document.querySelectorAll('figure').forEach(f=>f.hidden=f.id!=='capture-'+id)}buttons.forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));if(matchMedia('(max-width:520px)').matches)show('narrow');console.log('Portrait review ready',JSON.stringify({width:innerWidth,overflow:document.documentElement.scrollWidth>innerWidth,captures:buttons.length}));
+</script></body></html>`;
